import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 7;
    static final int MOD = 1000000007;
    static final long E100 = 570000004L;
    static int n;
    static int[][] g = new int[MAXN][MAXN];
    static long[][] nxt = new long[1 << MAXN][1 << MAXN];
    static int[] bitcnt = new int[1 << MAXN];
    static List<Integer>[] S = new ArrayList[MAXN + 1];
    static int[] id = new int[1 << MAXN];
    static Map<Long, Integer>[] dp = new HashMap[MAXN];

    static {
        for (int i = 0; i <= MAXN; i++) {
            S[i] = new ArrayList<>();
        }
        for (int i = 0; i < MAXN; i++) {
            dp[i] = new HashMap<>();
        }
    }

    static int process(int index, long mask) {
        if (mask == 0) return 0;
        if (index == n) return 1;
        if (dp[index].containsKey(mask)) return dp[index].get(mask);
        long sum_prob = 0;
        for (int mask_s = 0; mask_s < (1 << n); ++mask_s) {
            long prob = 1;
            for (int j = 0; j < n; ++j) {
                if (((mask_s & (1 << j)) != 0))
                    prob = (g[index][j] * prob) % MOD;
                else
                    prob = ((MOD + 1 - g[index][j]) * prob) % MOD;
            }
            long new_mask = 0;
            for (int b = 0; b < 35; ++b) {
                if (((1L << b) & mask) != 0)
                    new_mask |= nxt[mask_s][S[index][b]];
            }
            sum_prob = (sum_prob + prob * process(index + 1, new_mask)) % MOD;
        }
        int result = (int) sum_prob;
        dp[index].put(mask, result);
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        for (int i = 0; i < n; ++i) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; ++j) {
                g[i][j] = Integer.parseInt(parts[j]) * (int) E100 % MOD;
            }
        }
        for (int i = 1; i < (1 << n); ++i) {
            bitcnt[i] = bitcnt[i ^ (i & -i)] + 1;
        }
        for (int i = 0; i < (1 << n); ++i) {
            id[i] = S[bitcnt[i]].size();
            S[bitcnt[i]].add(i);
        }
        for (int i = 1; i < (1 << n); ++i) {
            for (int j = 0; j < (1 << n); ++j) {
                for (int k = 0; k < n; ++k) {
                    if (((i & (1 << k)) != 0) && ((j & (1 << k)) == 0))
                        nxt[i][j] |= 1L << id[j | (1 << k)];
                }
            }
        }
        int answer = process(0, 1);
        answer = ((answer % MOD) + MOD) % MOD;
        System.out.println(answer);
    }
}
